def _key(value):
    return re.sub(r"[\s_\-./()（）:%]+", "", unicodedata.normalize("NFKC", str(value or "")).strip().casefold())

_INDEX = {_key(k): v for k, v in ALIASES.items()}

def canonical_header(value):
    text = str(value or "").strip()
    return _INDEX.get(_key(text), text)

def canonical_sheet(value):
    return canonical_header(value)


def alias_record(record):
    """Add recognized English key aliases to an in-memory copy only.

    Original headers and values remain available for explicit column selection.
    Conflicting legacy/canonical columns are rejected rather than silently merged.
    """
    out=dict(record)
    for key,value in record.items():
        canonical=canonical_header(key)
        if canonical==key:
            continue
        if canonical in out and out[canonical] not in (None, '') and value not in (None, ''):
            a,b=out[canonical],value
            equivalent=str(a).strip()==str(b).strip()
            if not equivalent:
                try:equivalent=float(a)==float(b)
                except (TypeError,ValueError):pass
            if not equivalent:
                raise ValueError('Conflicting columns resolve to the same field: %r and %r' % (key,canonical))
        if canonical not in out or out[canonical] in (None, ''):
            out[canonical]=value
    return out
